bits 16
cpu 386
org 0x1000
%macro CASE 4
 mov word [0x8000],100
 mov al,%1
 out 0x80,al
%%loop:
 mov dx,0x300
 mov cx,2
 mov si,%3
 mov di,%3
 db %4
 dec word [0x8000]
 jnz %%loop
 mov al,%2
 out 0x80,al
%endmacro
start:
 cli
 cld
 xor ax,ax
 mov ds,ax
 mov es,ax
 mov ss,ax
 mov sp,0x7000
 mov word [0x8100],0x5555
 mov word [0x8102],0x5555
 CASE 0,1,0x8100,{0xf3,0x6c}
 CASE 2,3,0x8101,{0xf3,0x6c}
 CASE 4,5,0x8100,{0xf3,0x6d}
 CASE 6,7,0x8101,{0xf3,0x6d}
 CASE 8,9,0x8100,{0xf3,0x6e}
 CASE 10,11,0x8101,{0xf3,0x6e}
 CASE 12,13,0x8100,{0xf3,0x6f}
 CASE 14,15,0x8101,{0xf3,0x6f}
 mov al,0x55
 out 0x82,al
 out 0x8f,al
 hlt
